import six

from ute_common_abstract_core import scope
from ute_common_abstract_core.network_elem_identification import CellIdentification
from ute_common_abstract_core.singleton import Singleton
from . import lteuepool
from .ltebearer import BearerType, AutomaticBearerType
from .utils import cellfactory
from .utils.logs import get_all_loger_file_names  # create_zip_from_paths
from .config import loggers as ute_ue_logging
from .ue_capabilities import UeCapabilities


@six.add_metaclass(Singleton)
class TestEnv:
    """Test Environment object"""

    def __init__(self):
        """Basic initialization."""
        self._ues_pool = lteuepool.UeActivePools()
        self._all_ueproxy_log_paths = []

    def require_ue(self, ue_characteristics):
        """
        Find UE that fulfils given requirements and return that UE.

        :param ue_characteristics: encapsulated UE description
        :return: found UE - instance of LteUe (or derived)
        :raises: :py:class:`ute_ue.exceptions.RequiredUeNotFound`: If matching ue is not found
        """
        ue = self._ues_pool.get_ue(ue_characteristics)
        # ue is resource that need to be returned into pool when exiting current scope
        scope.current_scope().uses(resource=ue, resource_releaser=self.release_ue)

        ue.logger.info(f"testenv.require_ue({ue_characteristics}) has taken from UEs-pool: {ue}")
        return ue

    def require_ue_group(self, ue_characteristics, ues_number):
        """
        Find UEs that fulfils given requirements and store those UEs under given UE group alias.

        :param ue_characteristics: encapsulated UE description
        :param ues_number: size of requested group (nb of UEs to reserve)
        :return: None
        :raises: :py:class:`ute_ue.exceptions.NotEnoughRequiredUes`: If not enough matching ues found
        :raises: :py:class:`ute_common_abstract_core.exceptions.AliasAlreadyAssignedError`: if ue_alias already used for other UE
        """
        ue_group = self._ues_pool.get_ue_group(ue_characteristics=ue_characteristics, ues_number=ues_number)
        # ue-group is resource that need to be returned into pool when exiting current scope
        scope.current_scope().uses(resource=ue_group, resource_releaser=self.release_ue_group)
        msg = f"testenv.require_ue_group({ue_characteristics}, {ues_number}) has taken from UEs-pool: {ue_group}"
        ue_group.logger.info(msg)
        return ue_group

    def release_ue(self, ue):
        """
        Allow UE to be reused.

        :raises: :py:class:`ute_ue.exceptions.UnknownUe`: If given ue has not been returned via require_ue()
        :return: None
        """
        ue.logger.info(f"testenv.release_ue() releases to UEs-pool: {ue}")
        ue.reserved = False
        ue.gracefully_shutdown()  # if given UE type requires any specific switch-off/cleanup to let it be "fresh" UE before returning to ues-pool
        self._ues_pool.release_ue(ue)

    def release_ue_group(self, ue_group):
        """
        Allow UE-group to be reused.

        :raises: :py:class:`ute_ue.exceptions.UnknownUeGroup`: If given ue-group has not been returned via require_ue_group()
        :return: None
        """
        ue_group.logger.info(f"testenv.release_ue_group() releases to UEs-pool: {ue_group}")
        ue_group.shutdown()
        self._ues_pool.release_ue_group(ue_group=ue_group)

    def create_bearer_type(self, qci, pdn):
        """
        Creates BearerType object that identifies bearer (via qci/pdn pair)

        :param qci: QCI for bearer
        :param pdn: PDN for bearer
        :return: bearer type object
        """
        if (qci == 0) and (pdn == 1):
            bearer_type = AutomaticBearerType()
        else:
            bearer_identification = {'qci': qci, 'pdn': pdn}
            bearer_type = BearerType(bearer_identification)

        return bearer_type

    def create_ue_capabilities(self, hex=None, description=None):
        """
        Creates UeCapabilities object.

        UeCapabilities may be defined either via raw hex value
        or as description of required fields of ueCapabilityInformation.

        Either hex or description parameter should be provided (not both).

        :param hex: ue capabilities encoded as hex string starting from 0x
        :param description: ue capabilities as string describing fields of UeCapabilityInformation message
        :return: None
        """
        uecap = UeCapabilities(hex=hex, description=description)
        return uecap

    def require_cell(self, lnbts_id, lcr_id):
        """
        Create cell identification.

        :param lnbts_id: eNB identifier
        :param lcr_id: Local cell resource ID
        :return: created cell object - instance of LteCell (or derived)
        """
        infomodel_cell_id = {'enb_id': str(lnbts_id), 'cell_id': str(lcr_id)}
        cell_id = CellIdentification.from_type_id_pairs(identifiers=[('infomodel', infomodel_cell_id)])

        cell = cellfactory.create_cell(cell_id, self._ues_pool.get_active_pools_configuration())

        return cell

    def shutdown(self):
        """
        Shutdown all stuff started by testenv.

        :return: Tuple[bool, list]: Tuple with information if logs should be compressed and list of log paths
        """
        if self._ues_pool is not None:
            try:
                self._ues_pool.shutdown()
            except AttributeError as error:
                ute_ue_logging.mark_tc_phase(msg=f"NoneType' object has no attribute '{error}'")

        compress_all_logs = []
        for pool in self._ues_pool._active_pools:
            # legacy check and unit-test cases may not have pool_info
            if hasattr(pool, "pool_info") and "ueproxy_log_path" in pool.pool_info:
                self._all_ueproxy_log_paths.extend(list(pool.pool_info["ueproxy_log_path"]))
                compress_all_logs.append(pool.pool_info["compress_all_logs"])

        log_paths: list = get_all_loger_file_names()
        log_paths.extend(self._all_ueproxy_log_paths)

        return any(compress_all_logs), log_paths
